   306  static ssize_t url_decode(char *str)
   307  {
   308      if (UNLIKELY(!str))
   309          return -EINVAL;
   310
   311      char *ch, *decoded;
   312      for (decoded = ch = str; *ch; ch++) {
   313          if (*ch == '%') {
   314              char tmp =
   315                  (char)(decode_hex_digit(ch[1]) << 4 | decode_hex_digit(ch[2]));
   316
   317              if (UNLIKELY(!tmp))
   318                  return -EINVAL;
   319
   320              *decoded++ = tmp;
   321              ch += 2;
   322          } else if (*ch == '+') {
   323              *decoded++ = ' ';
   324          } else {
   325              *decoded++ = *ch;
   326          }
   327      }
   328
   329      *decoded = '\0';
   330      return (ssize_t)(decoded - str);
   331  }
