   347  static void parse_key_values(struct lwan_request *request,
   348                               struct lwan_value *helper_value,
   349                               struct lwan_key_value_array *array,
   350                               ssize_t (*decode_value)(char *value),
   351                               const char separator)
   352  {
   353      struct lwan_key_value *kv;
   354      char *ptr = helper_value->value;
   355      const char *end = helper_value->value + helper_value->len;
   356
   357      if (!helper_value->len)
   358          return;
   359
   360      lwan_key_value_array_init(array);
   361      /* Calling lwan_key_value_array_reset() twice is fine, so even if 'goto
   362       * error' is executed in this function, nothing bad should happen.  */
   363      coro_defer(request->conn->coro, reset_key_value_array, array);
   364
   365      do {
   366          char *key, *value;
   367
   368          while (*ptr == ' ' || *ptr == separator)
   369              ptr++;
   370          if (UNLIKELY(*ptr == '\0'))
   371              goto error;
   372
   373          key = ptr;
   374          ptr = strsep_char(key, end, separator);
   375
   376          value = strsep_char(key, end, '=');
   377          if (UNLIKELY(!value)) {
   378              value = "";
   379          } else if (UNLIKELY(decode_value(value) < 0)) {
   380              /* Disallow values that failed decoding, but allow empty values */
   381              goto error;
   382          }
   383
   384          if (UNLIKELY(decode_value(key) <= 0)) {
   385              /* Disallow keys that failed decoding, or empty keys */
   386              goto error;
   387          }
   388
   389          kv = lwan_key_value_array_append(array);
   390          if (UNLIKELY(!kv))
   391              goto error;
   392
   393          kv->key = key;
   394          kv->value = value;
   395      } while (ptr);
   396
   397      lwan_key_value_array_sort(array, key_value_compare);
   398
   399      return;
   400
   401  error:
   402      lwan_key_value_array_reset(array);
   403  }
