   541  static bool parse_headers(struct lwan_request_parser_helper *helper,
   542                            char *buffer)
   543  {
   544      char *buffer_end = helper->buffer->value + helper->buffer->len;
   545      char **header_start = helper->header_start;
   546      size_t n_headers = 0;
   547      char *next_header;
   548
   549      for (char *p = buffer + 1;;) {
   550          char *next_chr = p;
   551
   552          next_header = memchr(next_chr, '\r', (size_t)(buffer_end - p));
   553
   554          if (UNLIKELY(!next_header))
   555              return false;
   556
   557          if (next_chr == next_header) {
   558              if (buffer_end - next_chr > (ptrdiff_t)HEADER_TERMINATOR_LEN) {
   559                  STRING_SWITCH_SMALL (next_header) {
   560                  case STR2_INT('\r', '\n'):
   561                      helper->next_request = next_header + HEADER_TERMINATOR_LEN;
   562                  }
   563              }
   564              break;
   565          }
   566
   567          /* Is there at least a space for a minimal (H)eader and a (V)alue? */
   568          if (LIKELY(next_header - next_chr >= (ptrdiff_t)(sizeof("H: V") - 1))) {
   569              header_start[n_headers++] = next_chr;
   570
   571              if (UNLIKELY(n_headers >= N_HEADER_START - 1))
   572                  return false;
   573          } else {
   574              /* Better to abort early if there's no space. */
   575              return false;
   576          }
   577
   578          p = next_header + HEADER_TERMINATOR_LEN;
   579          if (UNLIKELY(p >= buffer_end))
   580              return false;
   581      }
   582
   583      header_start[n_headers] = next_header;
   584
   585      for (size_t i = 0; i < n_headers; i++) {
   586          char *p = header_start[i];
   587          char *end = header_start[i + 1] - HEADER_TERMINATOR_LEN;
   588
   589          STRING_SWITCH_L (p) {
   590          case STR4_INT_L('A', 'c', 'c', 'e'):
   591              p += HEADER_LENGTH("Accept");
   592
   593              STRING_SWITCH_L (p) {
   594              case STR4_INT_L('-', 'E', 'n', 'c'):
   595                  SET_HEADER_VALUE(accept_encoding, "-Encoding");
   596                  break;
   597              }
   598              break;
   599          case STR4_INT_L('C', 'o', 'n', 'n'):
   600              SET_HEADER_VALUE(connection, "Connection");
   601              break;
   602          case STR4_INT_L('C', 'o', 'n', 't'):
   603              p += HEADER_LENGTH("Content");
   604
   605              STRING_SWITCH_L (p) {
   606              case STR4_INT_L('-', 'T', 'y', 'p'):
   607                  SET_HEADER_VALUE(content_type, "-Type");
   608                  break;
   609              case STR4_INT_L('-', 'L', 'e', 'n'):
   610                  SET_HEADER_VALUE(content_length, "-Length");
   611                  break;
   612              }
   613              break;
   614          case STR4_INT_L('I', 'f', '-', 'M'):
   615              SET_HEADER_VALUE(if_modified_since.raw, "If-Modified-Since");
   616              break;
   617          case STR4_INT_L('R', 'a', 'n', 'g'):
   618              SET_HEADER_VALUE(range.raw, "Range");
   619              break;
   620          }
   621      }
   622
   623      helper->n_header_start = n_headers;
   624      return true;
   625  }
