   645  static void
   646  parse_range(struct lwan_request_parser_helper *helper)
   647  {
   648      if (UNLIKELY(helper->range.raw.len <= (sizeof("bytes=") - 1)))
   649          return;
   650
   651      char *range = helper->range.raw.value;
   652      if (UNLIKELY(strncmp(range, "bytes=", sizeof("bytes=") - 1)))
   653          return;
   654
   655      range += sizeof("bytes=") - 1;
   656      uint64_t from, to;
   657
   658      if (sscanf(range, "%"SCNu64"-%"SCNu64, &from, &to) == 2) {
   659          if (UNLIKELY(from > OFF_MAX || to > OFF_MAX))
   660              goto invalid_range;
   661
   662          helper->range.from = (off_t)from;
   663          helper->range.to = (off_t)to;
   664      } else if (sscanf(range, "-%"SCNu64, &to) == 1) {
   665          if (UNLIKELY(to > OFF_MAX))
   666              goto invalid_range;
   667
   668          helper->range.from = 0;
   669          helper->range.to = (off_t)to;
   670      } else if (sscanf(range, "%"SCNu64"-", &from) == 1) {
   671          if (UNLIKELY(from > OFF_MAX))
   672              goto invalid_range;
   673
   674          helper->range.from = (off_t)from;
   675          helper->range.to = -1;
   676      } else {
   677  invalid_range:
   678          helper->range.from = -1;
   679          helper->range.to = -1;
   680      }
   681  }
