   102  #define GENERATE_CASE_STMT(upper, lower, mask, constant)                       \
   103      case REQUEST_METHOD_##upper:                                               \
   104          return #upper;
   105
   106      switch (lwan_request_get_method(request)) {
   107          FOR_EACH_REQUEST_METHOD(GENERATE_CASE_STMT)
   108      default:
   109          return "UNKNOWN";
   110      }
   111
   112  #undef GENERATE_CASE_STMT
   113  }
