   115  static void log_request(struct lwan_request *request,
   116                          enum lwan_http_status status)
   117  {
   118      char ip_buffer[INET6_ADDRSTRLEN];
   119
   120      lwan_status_debug("%s [%s] \"%s %s HTTP/%s\" %d %s",
