   132  static inline bool has_response_body(enum lwan_request_flags method,
   133                                       enum lwan_http_status status)
   134  {
   135      /* See FOR_EACH_REQUEST_METHOD() in lwan.h */
   136      return (method & 1 << 0) || status != HTTP_NOT_MODIFIED;
   137  }
