   139  void lwan_response(struct lwan_request *request, enum lwan_http_status status)
   140  {
   141      const struct lwan_response *response = &request->response;
   142      char headers[DEFAULT_HEADERS_SIZE];
   143
   144      if (UNLIKELY(request->flags & RESPONSE_CHUNKED_ENCODING)) {
   145          /* Send last, 0-sized chunk */
   146          lwan_strbuf_reset(response->buffer);
   147          lwan_response_send_chunk(request);
   148          log_request(request, status);
   149          return;
   150      }
   151
   152      if (UNLIKELY(request->flags & RESPONSE_SENT_HEADERS)) {
   153          lwan_status_debug("Headers already sent, ignoring call");
   154          return;
   155      }
   156
   157      if (UNLIKELY(!response->mime_type)) {
   158          /* Requests without a MIME Type are errors from handlers that should
   159             just be handled by lwan_default_response().  */
   160          lwan_default_response(request, status);
   161          return;
   162      }
   163
   164      log_request(request, status);
   165
   166      if (request->flags & RESPONSE_STREAM) {
   167          if (LIKELY(response->stream.callback)) {
   168              status = response->stream.callback(request, response->stream.data);
   169          } else {
   170              status = HTTP_INTERNAL_ERROR;
   171          }
   172
   173          if (status >= HTTP_CLASS__CLIENT_ERROR) {
   174              request->flags &= ~RESPONSE_STREAM;
   175              lwan_default_response(request, status);
   176          }
   177
   178          return;
   179      }
   180
   181      size_t header_len =
   182          lwan_prepare_response_header(request, status, headers, sizeof(headers));
   183      if (UNLIKELY(!header_len)) {
   184          lwan_default_response(request, HTTP_INTERNAL_ERROR);
   185          return;
   186      }
   187
   188      if (!has_response_body(lwan_request_get_method(request), status)) {
   189          lwan_send(request, headers, header_len, 0);
   190          return;
   191      }
   192
   193      char *resp_buf = lwan_strbuf_get_buffer(response->buffer);
   194      const size_t resp_len = lwan_strbuf_get_length(response->buffer);
   195      if (sizeof(headers) - header_len > resp_len) {
   196          /* writev() has to allocate, copy, and validate the response vector,
   197           * so use send() for responses small enough to fit the headers
   198           * buffer.  On Linux, this is ~10% faster.  */
   199          memcpy(headers + header_len, resp_buf, resp_len);
   200          lwan_send(request, headers, header_len + resp_len, 0);
   201      } else {
   202          struct iovec response_vec[] = {
   203              {.iov_base = headers, .iov_len = header_len},
   204              {.iov_base = resp_buf, .iov_len = resp_len},
   205          };
   206
   207          lwan_writev(request, response_vec, N_ELEMENTS(response_vec));
   208      }
   209  }
