   211  void lwan_default_response(struct lwan_request *request,
   212                             enum lwan_http_status status)
   213  {
   214      request->response.mime_type = "text/html";
   215
   216      lwan_tpl_apply_with_buffer(
   217          error_template, request->response.buffer,
   218          &(struct error_template){
   219              .short_message = lwan_http_status_as_string(status),
   220              .long_message = lwan_http_status_as_descriptive_string(status),
   221          });
   222
   223      lwan_response(request, status);
   224  }
