   226  #define RETURN_0_ON_OVERFLOW(len_)                                             \
   227      if (UNLIKELY(p_headers + (len_) >= p_headers_end))                         \
   228      return 0
   229
   230  #define APPEND_STRING_LEN(const_str_, len_)                                    \
   231      do {                                                                       \
   232          RETURN_0_ON_OVERFLOW(len_);                                            \
   233          p_headers = mempcpy(p_headers, (const_str_), (len_));                  \
   234      } while (0)
   235
   236  #define APPEND_STRING(str_)                                                    \
   237      do {                                                                       \
   238          size_t len = strlen(str_);                                             \
   239          APPEND_STRING_LEN((str_), len);                                        \
   240      } while (0)
   241
   242  #define APPEND_CHAR(value_)                                                    \
   243      do {                                                                       \
   244          RETURN_0_ON_OVERFLOW(1);                                               \
   245          *p_headers++ = (value_);                                               \
   246      } while (0)
